def is_regular(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def longest_regular_substrings(s):
    n = len(s)
    max_length = 0
    count = 0
    stack = []

    for i in range(n):
        if s[i] == '(':
            stack.append(i)
        else:
            if stack:
                start = stack.pop()
                length = i - start + 1
                if length > max_length:
                    max_length = length
                    count = 1
                elif length == max_length:
                    count += 1

    if max_length == 0:
        return "0 1"
    else:
        return f"{max_length} {count}"

